python3 << 'EOF'
from elftools.elf.elffile import ELFFile
import bisect

# The SGen worker addresses aren't resolving well from .symtab alone.
# Let's try DWARF info for those addresses and also use the .dynsym
addresses = [0x2f4b20, 0x2f4c84]

with open('/tmp/sv-309cf567c72e403e986ee027be3a4e6f/symbols/libmonosgen-2.0.so.dbg', 'rb') as f:
    elf = ELFFile(f)

    if elf.has_dwarf_info():
        dwarf = elf.get_dwarf_info()
        for addr in addresses:
            # Use aranges if available
            found = False
            for CU in dwarf.iter_CUs():
                # Check line program for this CU
                try:
                    line_prog = dwarf.line_program_for_CU(CU)
                    if line_prog is None:
                        continue
                    # Get the function from DIEs
                    for DIE in CU.iter_DIEs():
                        if DIE.tag == 'DW_TAG_subprogram':
                            low_pc = DIE.attributes.get('DW_AT_low_pc')
                            high_pc = DIE.attributes.get('DW_AT_high_pc')
                            name = DIE.attributes.get('DW_AT_name')
                            if low_pc and high_pc and name:
                                lo = low_pc.value
                                hi = high_pc.value
                                if high_pc.form in ('DW_FORM_data1', 'DW_FORM_data2', 'DW_FORM_data4', 'DW_FORM_data8', 'DW_FORM_udata'):
                                    hi = lo + hi  # high_pc is offset
                                if lo <= addr < hi:
                                    print(f"  0x{addr:08x} => {name.value.decode()}+0x{addr-lo:x}")
                                    found = True
                                    break
                except Exception:
                    continue
                if found:
                    break
            if not found:
                print(f"  0x{addr:08x} => (not found in DWARF)")
EOF

