{"command": "python3 << 'EOF'
from elftools.elf.elffile import ELFFile
from elftools.dwarf.descriptions import describe_form_class

addresses = [0x222098, 0x2241ac, 0x1abc80, 0x16de04, 0x2c1a40]

with open('/tmp/sv-309cf567c72e403e986ee027be3a4e6f/symbols/libmonosgen-2.0.so.dbg', 'rb') as f:
    elf = ELFFile(f)
    dwarf = elf.get_dwarf_info()

    for CU in dwarf.iter_CUs():
        line_prog = dwarf.line_program_for_CU(CU)
        if line_prog is None:
            continue

        # Build line table
        entries = line_prog.get_entries()
        prev_state = None
        for entry in entries:
            state = entry.state
            if state is None:
                continue
            if prev_state and not prev_state.end_sequence:
                for addr in addresses[:]:
                    if prev_state.address <= addr < state.address:
                        file_entry = line_prog['file_entry'][prev_state.file - 1]
                        dir_idx = file_entry.dir_index
                        if dir_idx > 0:
                            directory = line_prog['include_directory'][dir_idx - 1]
                            filename = directory.decode() + '/' + file_entry.name.decode()
                        else:
                            filename = file_entry.name.decode()
                        print(f"  0x{addr:08x} => {filename}:{prev_state.line}")
                        addresses.remove(addr)
            prev_state = state

    for addr in addresses:
        print(f"  0x{addr:08x} => (no line info)")
EOF", "description": "Get DWARF line info for addresses", "initial_wait": 60}
